#!/usr/bin/env python3
"""Compute deterministic numeric ground truth for CSX-310_Q2."""

from __future__ import annotations

import json
import re
from html import unescape
from pathlib import Path
from typing import Any


TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = TASK_DIR.parents[2]
PACKAGE_ROOT = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / "CSX-310"
OUTPUT_PATH = TASK_DIR / "computed_gt.json"

TARGET_FAMILY = "hunga_tonga_surface_change_weather_null_consistency"

SOURCE_FILES = [
    "metadata/event.json",
    "data/event_reports/event_reports_001_Locked_package_evidence_report.html",
    "data/event_catalogs/event_catalogs_005_04_event_specific_disaster_catalog_GDACS_event_list_for_package_time_window.json.json",
    "data/remote_sensing/remote_sensing_004_Sentinel-1_GRD_VV_pre_post_change.json",
    "data/physical_hazard/physical_hazard_006_Sentinel-2_SR_Harmonized_dNBR.json",
    "data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json",
    "data/physical_hazard/physical_hazard_003_ERA5-Land_hourly_aggregate_stats.json",
]


def load_json(rel_path: str) -> Any:
    with (PACKAGE_ROOT / rel_path).open("r", encoding="utf-8-sig") as handle:
        return json.load(handle)


def load_html_text(rel_path: str) -> str:
    raw = (PACKAGE_ROOT / rel_path).read_text(encoding="utf-8-sig", errors="replace")
    raw = re.sub(r"(?is)<script.*?</script>|<style.*?</style>", " ", raw)
    raw = re.sub(r"(?s)<[^>]+>", " ", raw)
    return re.sub(r"\s+", " ", unescape(raw)).strip().lower()


def round_float(value: float, digits: int = 4) -> float:
    return round(float(value), digits)


def build_rubric() -> dict[str, Any]:
    return {
        "total_points": 20,
        "criteria": [
            {
                "name": "Requested JSON form",
                "points": 4,
                "description": (
                    "Returns compact JSON with target_family, metrics, gates, final_label, "
                    "and computed_consequence."
                ),
            },
            {
                "name": "Numeric anchors and formulas",
                "points": 5,
                "description": (
                    "Computes the maximum absolute all-weather VV change, the VV change-to-std ratio, "
                    "the optical peak-to-mean ratio, event precipitation maximum, coverage balance, "
                    "and event anchor score with correct units or unit-implied names."
                ),
            },
            {
                "name": "Threshold gates",
                "points": 4,
                "description": (
                    "Applies the all-weather, optical-support, weather-null, and event-anchor gates "
                    "using the stated inequalities and reaches the correct final label."
                ),
            },
            {
                "name": "Component reasoning",
                "points": 3,
                "description": (
                    "Shows how the max, ratio, balance, and indicator calculations were derived "
                    "from the package values rather than listing raw numbers only."
                ),
            },
            {
                "name": "Computed rejection",
                "points": 2,
                "description": (
                    "Rejects weather variability as the main numeric explanation because precipitation "
                    "is below the 1 mm guardrail while surface-change gates pass."
                ),
            },
            {
                "name": "Concise consequence",
                "points": 1,
                "description": "Keeps the event-process label short and tied to the computed gates.",
            },
            {
                "name": "No overreach",
                "points": 1,
                "description": (
                    "Avoids treating exposure context, plume height alone, or any single image layer "
                    "as confirmed loss accounting."
                ),
            },
        ],
    }


def compute() -> dict[str, Any]:
    event = load_json(SOURCE_FILES[0])
    report_text = load_html_text(SOURCE_FILES[1])
    gdacs = load_json(SOURCE_FILES[2])
    s1 = load_json(SOURCE_FILES[3])
    s2 = load_json(SOURCE_FILES[4])
    gpm = load_json(SOURCE_FILES[5])
    era5 = load_json(SOURCE_FILES[6])

    gdacs_props = gdacs["features"][0]["properties"]
    s1_counts = s1["counts"]
    s1_stats = s1["stats"]
    s2_stats = s2["stats"]
    gpm_stats = gpm["stats"]
    era5_stats = era5["stats"]

    plume_heights = [float(match) for match in re.findall(r"(\d+(?:\.\d+)?)\s+kilometers", report_text)]
    plume_height_km = max(plume_heights)

    s1_abs_change_db = max(
        abs(float(s1_stats["s1_vv_post_minus_pre_db_min"])),
        abs(float(s1_stats["s1_vv_post_minus_pre_db_max"])),
    )
    s1_signal_to_std = s1_abs_change_db / float(s1_stats["s1_vv_post_minus_pre_db_stdDev"])
    optical_peak_to_mean = (
        float(s2_stats["sentinel2_dnbr_max"]) / float(s2_stats["sentinel2_dnbr_mean"])
    )
    event_precip_max_mm = max(
        float(gpm_stats["gpm_event_precip_mm_max"]),
        float(era5_stats["precipitation_sum_mm_max"]),
    )
    pre_count = int(s1_counts["pre_count"])
    post_count = int(s1_counts["post_count"])
    coverage_balance = min(pre_count, post_count) / max(pre_count, post_count)
    alert_score = float(gdacs_props["alertscore"])
    event_anchor_score = int(alert_score >= 3.0) + int(plume_height_km >= 40.0)

    metrics = {
        "s1_abs_change_db": round_float(s1_abs_change_db, 4),
        "s1_signal_to_std": round_float(s1_signal_to_std, 4),
        "optical_peak_to_mean": round_float(optical_peak_to_mean, 4),
        "event_precip_max_mm": round_float(event_precip_max_mm, 4),
        "coverage_balance": round_float(coverage_balance, 4),
        "event_anchor_score": event_anchor_score,
    }

    gates = {
        "all_weather_gate": (
            metrics["s1_abs_change_db"] >= 10.0
            and metrics["s1_signal_to_std"] >= 10.0
            and pre_count >= 10
            and post_count >= 10
            and metrics["coverage_balance"] >= 0.8
        ),
        "optical_support_gate": (
            float(s2_stats["sentinel2_dnbr_max"]) >= 0.5
            and metrics["optical_peak_to_mean"] >= 10.0
        ),
        "weather_null_gate": metrics["event_precip_max_mm"] < 1.0,
        "event_anchor_gate": event_anchor_score == 2,
    }
    final_label = (
        "event_window_surface_change_weather_null_pass"
        if all(gates.values())
        else "event_window_surface_change_weather_null_fail"
    )

    primary_gt = {
        "target_family": TARGET_FAMILY,
        "metrics": metrics,
        "gates": gates,
        "final_label": final_label,
        "computed_consequence": "weather_variability_rejected_by_precip_gate",
        "tolerances": {
            "s1_abs_change_db": 0.0001,
            "s1_signal_to_std": 0.001,
            "optical_peak_to_mean": 0.001,
            "event_precip_max_mm": 0.0001,
            "coverage_balance": 0.0001,
            "event_anchor_score": 0,
        },
    }

    return {
        "schema_version": "1.0",
        "task_id": "CSX-310_Q2",
        "event_id": "CSX-310",
        "target_family": TARGET_FAMILY,
        "task_type": "numeric",
        "evaluation_mode": "deterministic",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "rubric": build_rubric(),
        "event": {
            "package_id": "CSX-310",
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "event_date_or_window": "2021-12-20 to 2022-01-18; main eruption-tsunami date 2022-01-15",
        },
        "decision_rule": {
            "summary": (
                "All four gates must pass: strong event-window all-weather change, optical support, "
                "near-zero event-day precipitation, and a two-part event anchor."
            ),
            "formulas": {
                "s1_abs_change_db": "max(abs(vv_change_min), abs(vv_change_max))",
                "s1_signal_to_std": "s1_abs_change_db / vv_change_stdDev",
                "optical_peak_to_mean": "optical_change_max / optical_change_mean",
                "event_precip_max_mm": "max(gridded_precip_max, reanalysis_precip_sum_max)",
                "coverage_balance": "min(pre_count, post_count) / max(pre_count, post_count)",
                "event_anchor_score": "I(alert_score >= 3.0) + I(plume_height_km >= 40.0)",
            },
            "thresholds": {
                "all_weather_gate": "s1_abs_change_db >= 10, s1_signal_to_std >= 10, pre_count >= 10, post_count >= 10, coverage_balance >= 0.8",
                "optical_support_gate": "optical_change_max >= 0.5 and optical_peak_to_mean >= 10",
                "weather_null_gate": "event_precip_max_mm < 1.0",
                "event_anchor_gate": "event_anchor_score == 2",
            },
        },
        "key_values": {
            "s1_counts": {"pre_count": pre_count, "post_count": post_count},
            "s1_change_db": {
                "min": round_float(s1_stats["s1_vv_post_minus_pre_db_min"], 4),
                "max": round_float(s1_stats["s1_vv_post_minus_pre_db_max"], 4),
                "stdDev": round_float(s1_stats["s1_vv_post_minus_pre_db_stdDev"], 4),
            },
            "optical_change": {
                "max": round_float(s2_stats["sentinel2_dnbr_max"], 4),
                "mean": round_float(s2_stats["sentinel2_dnbr_mean"], 4),
            },
            "precipitation_mm": {
                "gridded_max": round_float(gpm_stats["gpm_event_precip_mm_max"], 4),
                "reanalysis_sum_max": round_float(era5_stats["precipitation_sum_mm_max"], 4),
            },
            "event_anchor_inputs": {
                "alert_level": gdacs_props["alertlevel"],
                "alert_score": round_float(alert_score, 2),
                "plume_height_km": round_float(plume_height_km, 1),
            },
        },
        "numeric_tolerances": {
            "s1_abs_change_db": {"target": metrics["s1_abs_change_db"], "absolute_tolerance": 0.0001},
            "s1_signal_to_std": {"target": metrics["s1_signal_to_std"], "absolute_tolerance": 0.001},
            "optical_peak_to_mean": {"target": metrics["optical_peak_to_mean"], "absolute_tolerance": 0.001},
            "event_precip_max_mm": {"target": metrics["event_precip_max_mm"], "absolute_tolerance": 0.0001},
            "coverage_balance": {"target": metrics["coverage_balance"], "absolute_tolerance": 0.0001},
            "event_anchor_score": {"target": event_anchor_score, "absolute_tolerance": 0},
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
            "notes": "Deterministic local-file calculation with fixed formulas and numeric tolerances.",
        },
    }


def main() -> None:
    result = compute()
    OUTPUT_PATH.write_text(json.dumps(result, indent=2, sort_keys=False) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
